import{_ as l,a0 as o,w as d,s as r,ao as t,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"千面 awk | LCTT x X-CMD","titleTemplate":false,"description":"千面 awk | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"千面 awk | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"千面 awk | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191125 The many faces of awk","title":"千面 awk","tag":"201912","desc":""},"relativePath":"201912/20191125 The many faces of awk.md","filePath":"[post].md"}'),c={name:"201912/20191125 The many faces of awk.md"};function h(k,s,g,u,b,f){const n=o("Link");return d(),r("div",null,[s[20]||(s[20]=t(`<h1 id="千面-awk" tabindex="-1">千面 awk <a class="header-anchor" href="#千面-awk" aria-label="Permalink to “千面 awk”">​</a></h1><blockquote><p><code>awk</code> 命令不僅提供了簡單的輸入字符串篩選功能，還包含提取數據列、打印簡單文本、篩選內容——甚至做一些數學計算。</p></blockquote><p><img src="https://images.techhive.com/images/article/2015/09/thinkstockphotos-512100549-100611755-large.jpg" alt="Thinkstock"></p><p>如果你僅使用 <code>awk</code> 選取一行中的特定文本，那麼你可能錯過了它的很多功能。在這篇文章中，我們會來看看使用 <code>awk</code> 可以幫你做一些其他的什麼事情，並提供一些例子。</p><h3 id="提取數據列" tabindex="-1">提取數據列 <a class="header-anchor" href="#提取數據列" aria-label="Permalink to “提取數據列”">​</a></h3><p><code>awk</code> 所提供的最簡單與最常用的功能便是從文件或管道傳輸的數據中選取特定的內容。默認使用空格當做分隔符，這非常簡單。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo one two three four five | awk ‘{print $4}’</span></span>
<span class="line"><span>four</span></span>
<span class="line"><span>$ who | awk ‘{print $1}’</span></span>
<span class="line"><span>jdoe</span></span>
<span class="line"><span>fhenry</span></span></code></pre></div><p>空格指的是一系列的 <code>space</code> 或 <code>tab</code> 字符。在下面所展示的命令裏，<code>awk</code> 從提供的數據中篩選第一和第四項。</p><p><code>awk</code> 命令也可以通過在其後增加文件名參數的方式從文本文件中獲取數據。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;{print $1,$5,$NF}&#39; HelenKellerQuote</span></span>
<span class="line"><span>The beautiful heart.</span></span></code></pre></div><p>（LCTT 譯註：“The best and most beautiful things in the world can not be seen or even touched , they must be felt with heart.” ——海倫凱勒）</p><p>在這個例子中，<code>awk</code> 挑選了一行中的第一個、第五個和最後一個字段。</p><p>命令中的 <code>$NF</code> 指定選取每行的最後一個字段。這是因為 <code>NF</code> 代表一行中的<ruby>字段數量<rt>Number of Field</rt></ruby>，也就是 23，而 <code>$NF</code> 就代表着那個字段的值，也就是<code>heart</code>。最後的句號也包含進去了，因為它是最後一個字符串的一部分。</p><p>字段能以任何有用的形式打印。在這個例子中，我們將字段以日期的格式進行打印輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date | awk &#39;{print $4,$3,$2}&#39;</span></span>
<span class="line"><span>2019 Nov 22</span></span></code></pre></div><p>如果你省略了 <code>awk</code> 命令中字段指示符之間的逗號，輸出將會擠成一個字符串。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date | awk &#39;{print $4 $3 $2}&#39;</span></span>
<span class="line"><span>2019Nov21</span></span></code></pre></div><p>如果你將通常使用的逗號替換為連字符，<code>awk</code> 就會嘗試將兩個字段的值相減——或許這並不是你想要的。它不會將連字符插入到輸出結果中。相反地，它對輸出做了一些數學計算。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date | awk &#39;{print $4-$3-$2}&#39;</span></span>
<span class="line"><span>1997</span></span></code></pre></div><p>在這個例子中，它將年 “2019” 和日期 “22” 相減，並忽略了中間的 “Nov”。</p><p>如果你想要空格之外的字符作為輸出分隔符，你可以通過 <code>OFS</code>（<ruby>輸出分隔符<rt>output field separator</rt></ruby>）指定分隔符，就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date | awk &#39;{OFS=&quot;-&quot;; print $4,$3,$2}&#39;</span></span>
<span class="line"><span>2019-Nov-22</span></span></code></pre></div><h3 id="打印簡單文本" tabindex="-1">打印簡單文本 <a class="header-anchor" href="#打印簡單文本" aria-label="Permalink to “打印簡單文本”">​</a></h3><p>你也可以使用 <code>awk</code> 簡單地顯示一些文本。當然了，比起 <code>awk</code> 你可能更想使用 <code>echo</code> 命令。但換句話説，作為 <code>awk</code> 腳本的一部分，打印某些相關性文本將會非常實用。這裏有一個沒什麼用的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;BEGIN {print &quot;Hello, World&quot; }&#39;</span></span>
<span class="line"><span>Hello, World</span></span></code></pre></div><p>下面的例子更加合理，添加一行文本標籤來更好的辨識數據。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ who | awk &#39;BEGIN {print &quot;Current logins:&quot;} {print $1}&#39;</span></span>
<span class="line"><span>Current logins:</span></span>
<span class="line"><span>shs</span></span>
<span class="line"><span>nemo</span></span></code></pre></div><h3 id="指定字段分隔符" tabindex="-1">指定字段分隔符 <a class="header-anchor" href="#指定字段分隔符" aria-label="Permalink to “指定字段分隔符”">​</a></h3><p>不是所有的輸入都以空格作為分隔符的。如果你的文本通過其它的字符作為分隔符（例如：逗號、冒號、分號），你可以通過 <code>-F</code> 選項（輸入分隔符）告訴 <code>awk</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat testfile</span></span>
<span class="line"><span>a:b:c,d:e</span></span>
<span class="line"><span>$ awk -F : &#39;{print $2,$3}&#39; testfile</span></span>
<span class="line"><span>b c,d</span></span></code></pre></div><p>下面是一個更加有用的例子——從冒號分隔的 <code>/etc/passwd</code> 文件中獲取數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk -F: &#39;{print $1}&#39; /etc/passwd | head -11</span></span>
<span class="line"><span>root</span></span>
<span class="line"><span>daemon</span></span>
<span class="line"><span>bin</span></span>
<span class="line"><span>sys</span></span>
<span class="line"><span>sync</span></span>
<span class="line"><span>games</span></span>
<span class="line"><span>man</span></span>
<span class="line"><span>lp</span></span>
<span class="line"><span>mail</span></span>
<span class="line"><span>news</span></span>
<span class="line"><span>uucp</span></span></code></pre></div><h3 id="篩選內容" tabindex="-1">篩選內容 <a class="header-anchor" href="#篩選內容" aria-label="Permalink to “篩選內容”">​</a></h3><p>你也可以使用 <code>awk</code> 命令評估字段。例如你僅僅想列出 <code>/etc/passwd</code> 中的用户賬號，就可以對第三個字段做一些篩選。下面的例子中我們只關注大於等於 1000 的 UID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk -F&quot;:&quot; &#39; $3 &gt;= 1000 &#39; /etc/passwd</span></span>
<span class="line"><span>nobody:x:65534:65534:nobody:/nonexistent:/usr/sbin/nologin</span></span>
<span class="line"><span>shs:x:1000:1000:Sandra Henry-Stocker,,,:/home/shs:/bin/bash</span></span>
<span class="line"><span>nemo:x:1001:1001:Nemo,,,:/home/nemo:/usr/bin/zsh</span></span>
<span class="line"><span>dory:x:1002:1002:Dory,,,:/home/dory:/bin/bash</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>如果你想為輸出增加標題，可以添加 <code>BEGIN</code> 從句：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk -F&quot;:&quot; &#39;BEGIN {print &quot;user accounts:&quot;} $3 &gt;= 1000 &#39; /etc/passwd</span></span>
<span class="line"><span>user accounts:</span></span>
<span class="line"><span>nobody:x:65534:65534:nobody:/nonexistent:/usr/sbin/nologin</span></span>
<span class="line"><span>shs:x:1000:1000:Sandra Henry-Stocker,,,:/home/shs:/bin/bash</span></span>
<span class="line"><span>nemo:x:1001:1001:Nemo,,,:/home/nemo:/usr/bin/zsh</span></span>
<span class="line"><span>dory:x:1002:1002:Dory,,,:/home/dory:/bin/bash</span></span></code></pre></div><p>如果你想要不止一行的標題，你可以通過 <code>&quot;\\n&quot;</code> 分隔輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk -F&quot;:&quot; &#39;BEGIN {print &quot;user accounts\\n=============&quot;} $3 &gt;= 1000 &#39; /etc/passwd</span></span>
<span class="line"><span>user accounts</span></span>
<span class="line"><span>=============</span></span>
<span class="line"><span>nobody:x:65534:65534:nobody:/nonexistent:/usr/sbin/nologin</span></span>
<span class="line"><span>shs:x:1000:1000:Sandra Henry-Stocker,,,:/home/shs:/bin/bash</span></span>
<span class="line"><span>nemo:x:1001:1001:Nemo,,,:/home/nemo:/usr/bin/zsh</span></span>
<span class="line"><span>dory:x:1002:1002:Dory,,,:/home/dory:/bin/bash</span></span></code></pre></div><h3 id="在-awk-中進行數學計算" tabindex="-1">在 awk 中進行數學計算 <a class="header-anchor" href="#在-awk-中進行數學計算" aria-label="Permalink to “在 awk 中進行數學計算”">​</a></h3><p><code>awk</code> 提供了驚人的數學計算能力，並且可以開平方，算 <code>log</code>，算 <code>tan</code> 等等。</p><p>這裏有一對例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;BEGIN {print sqrt(2019)}&#39;</span></span>
<span class="line"><span>44.9333</span></span>
<span class="line"><span>$ awk &#39;BEGIN {print log(2019)}&#39;</span></span>
<span class="line"><span>7.61036</span></span></code></pre></div>`,43)),i("p",null,[s[1]||(s[1]=a("想要詳細瞭解 ",-1)),s[2]||(s[2]=i("code",null,"awk",-1)),s[3]||(s[3]=a(" 的數學計算能力，可以看《",-1)),e(n,{href:"https://www.networkworld.com/article/2974753/doing-math-with-awk.html"},{default:p(()=>[...s[0]||(s[0]=[a("使用 awk 進行數學計算",-1)])]),_:1}),s[4]||(s[4]=a("》這篇文章。",-1))]),s[21]||(s[21]=t(`<h3 id="awk-腳本" tabindex="-1">awk 腳本 <a class="header-anchor" href="#awk-腳本" aria-label="Permalink to “awk 腳本”">​</a></h3><p>你也可以使用 <code>awk</code> 寫一套單獨的腳本。下面的例子模仿了之前寫過的一個，不過還計算了系統裏賬户的數量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/awk -f</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 這一行是註釋</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BEGIN {</span></span>
<span class="line"><span>    printf &quot;%s\\n&quot;,&quot;User accounts:&quot;</span></span>
<span class="line"><span>    print &quot;==============&quot;</span></span>
<span class="line"><span>    FS=&quot;:&quot;</span></span>
<span class="line"><span>    n=0</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 現在開始遍歷數據</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    if ($3 &gt;= 1000) {</span></span>
<span class="line"><span>        print $1</span></span>
<span class="line"><span>        n ++</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>END {</span></span>
<span class="line"><span>    print &quot;==============&quot;</span></span>
<span class="line"><span>    print n &quot; accounts&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>注意 <code>BEGIN</code> 那一節是如何提供標題、指定字段分隔符和初始化計數器的，它僅在腳本初始化時期執行。這個腳本也包含 <code>END</code> 節，它僅在中間所有命令處理完成之後運行，顯示了所有中間小節所篩選數據的最終行數（第三個字段大於等於 1000）。</p><p>作為一個長存於 Unix 之上的命令，<code>awk</code> 依舊提供着非常有用的服務，這也是我幾十年前愛上 Unix 的原因之一。</p><hr>`,6)),i("p",null,[s[6]||(s[6]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3454979/the-many-faces-of-awk.html"},{default:p(()=>[...s[5]||(s[5]=[a("https://www.networkworld.com/article/3454979/the-many-faces-of-awk.html",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[7]||(s[7]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[12]||(s[12]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 譯者：",-1)),e(n,{href:"https://github.com/LuuMing"},{default:p(()=>[...s[9]||(s[9]=[a("LuuMing",-1)])]),_:1}),s[14]||(s[14]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const x=l(c,[["render",h]]);export{y as __pageData,x as default};
